from pathlib import Path
import subprocess,json,sys,hashlib,datetime
from checksums import checksum
root=Path(__file__).resolve().parents[2];out=Path(__file__).resolve().parent
plan=json.loads((out/'plan.json').read_text());accepted={};results={};commands=[]
def save(name,value): (out/name).write_text(json.dumps(value,indent=2)+'\n')
def series(item,stage,tag,n,rounds):
 slug=item['slug'];c={**item,'iterations':n,'checksum_expected':checksum(item['case'],n)};config=slug+'-config.json';save(config,c)
 rows=[]
 for index in (1,2):
  cmd=[sys.executable,str(out/'worker.py')] if item['platform']=='windows' else ['wsl','--exec','python3','/mnt/d/home/source/zig/forthz/.work/catch-copy-20261116/worker.py']
  cmd += [stage,'--series',str(index),'--config',config,'--cpu',str(item['cpu']),'--rounds',str(rounds),'--tag',tag]
  commands.append(cmd);save('commands.json',commands)
  with (out/(tag+f'-{stage}-{index}.log')).open('wb') as f:r=subprocess.run(cmd,cwd=root,stdout=f,stderr=subprocess.STDOUT)
  assert r.returncode==0,(stage,tag,index,r.returncode)
  row=json.loads((out/(tag+f'-{stage}-{index}.json')).read_text());assert row['checksum']==c['checksum_expected'];rows.append(row)
 return rows
validation=json.loads((out/'validation.json').read_text());assert len(validation)==10
for row in validation:
 assert row['exit']==0 or (len(row.get('elf_tests',[]))==2 and all(x['exit']==0 for x in row['elf_tests']))
manifest={}
for kind in ('baseline','candidate'):
 for platform in ('windows','linux'):
  b=out/(kind+'-'+platform)/'bin'/('sigma.exe' if platform=='windows' else 'sigma');manifest[kind+'-'+platform]={'sha256':hashlib.sha256(b.read_bytes()).hexdigest(),'bytes':b.stat().st_size}
save('frozen-binaries.json',manifest)
save('timing-start.json',{'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'validation_complete':True,'protocol_sha256':hashlib.sha256((out/'protocol.json').read_bytes()).hexdigest()})
for item in plan:
 slug=item['slug'];n=item['iterations'];ok=False
 for attempt in range(3):
  for rounds in (5,15,31):
   tag=slug+f'-c{attempt}-r{rounds}';rows=series(item,'aa',tag,n,rounds)
   minimum=min(r['engines'][engine]['median_us'] for r in rows for engine in ('A1','A2'));delta=max(r['aa_delta_percent'] for r in rows)
   print('AA',slug,n,rounds,'delta',round(delta,3),'min_us',minimum,flush=True)
   if minimum>=1000000 and delta<=2:
    accepted[slug]={'iterations':n,'rounds':rounds,'delta_percent':delta,'tag':tag};save('accepted-aa.json',accepted);ok=True;break
   if minimum<1000000:break
  if ok:break
  n*=2
 if not ok:
  save('calibration-stop.json',{'case':slug,'reason':'Maximum three iteration settings exhausted; no candidate comparison allowed','completed':len(accepted)});raise SystemExit(2)
save('calibration-complete.json',accepted)
for item in plan:
 slug=item['slug'];a=accepted[slug];rows=series(item,'compare',slug+'-final',a['iterations'],max(7,a['rounds']));changes=[r['change_percent'] for r in rows]
 key=item['case'];delta=a['delta_percent'];limit=10 if key in ('catch/throw','catch/fast-throw','catch/nobt-throw') else 5 if key.startswith('catch/') else max(3,2*delta)
 primary=all(-x>=10 and -x>2*delta for x in changes) if key in ('normal/arithmetic','normal/loops') else None
 results[slug]={'platform':item['platform'],'case':key,'calibration':a,'changes_percent':changes,'limit_percent':limit,'within_worsening_limit':all(x<=limit for x in changes),'primary_condition':primary}
 save('results.json',results);print('AB',slug,[round(x,3) for x in changes],flush=True)
save('timing-complete.json',{'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'conditions':len(results)})

