def checksum(key,n):
 if key.startswith('catch/'):
  return 0 if key.startswith('catch/nested-') else n*(77 if key in ['catch/throw','catch/fast-throw','catch/nobt-throw'] else 1)
 name=key.split('/')[1]
 if name=='stacks':return 3+((3+3*(n//2)+n%2)&65535)
 if name=='calls':return 4*n
 if name=='variables':return 7*n
 if name=='loops':return 28*(n//8)+sum(range(n%8))
 if name=='plus-loop':return 12*(n//8)+sum(range(0,n%8,2))
 if name=='float':return n
 x=1;seen={};values=[]
 while x not in seen:
  if len(values)==n:return x
  seen[x]=len(values);values.append(x)
  if name=='arithmetic':x=(3*x+7)&65535
  elif name=='extended':
   y=2*x+1;x=(y^(y>>3))&65535
  else:raise ValueError(key)
 start=seen[x];return values[start+(n-start)%(len(values)-start)]

